 "injuries": [
  {
   "label": "Lower back & sciatica",
   "text": "All core work uses anti-flexion and anti-rotation patterns only. Never do sit-ups, weighted crunches, or loaded spinal flexion. Sharp back pain or sciatic tingling → stop, switch to Mobility Variant B post-session, rest the next day. Symptoms beyond 48 hours → physiotherapy before continuing."
  },
  {
   "label": "Coccyx",
   "text": "Cushion under knees in all seated stretches. Avoid direct tailbone pressure in floor exercises. If split squats or step-ups cause tailbone discomfort, reduce depth or substitute glute bridges."
  },
  {
   "label": "Finger capsulitis",
   "text": "Favour open-hand and half-crimp throughout. Avoid full crimp while symptomatic. Finger & wrist care (Mobility, Post-workout Variant C) after upper-body and climbing sessions is non-negotiable — maintain it even on reduced-volume weeks. Acutely swollen or painful joint → skip loading, passive range-of-motion only."
  },
  {
   "label": "Wrist pain",
   "text": "The finger-extensor strength work in your upper-body sessions and Mobility Variant C exist specifically for this. Do not skip them. If wrist pain increases after a session, ice for 10–15 min and note which grip preceded it."
  }
 ],
