    {
     "day": "Friday",
     "title": "Climbing: First Project Attempts",
     "pre": "C or E",
     "post": "C or E",
     "items": [
      {
       "text": "Warm up thoroughly — 20 min on the wall at easy grade.",
       "name": "Warm up thoroughly",
       "detail": "20 min on the wall at easy grade.",
       "id": "warm-up-thoroughly"
      },
      {
       "text": "Identify 1–2 problems at absolute limit (V6+). Attempt each 2–3 times with 4-min full rests. Quality only — stop if too pumped to climb technically.",
       "id": "identify-1-2-problems-at-abs"
      },
      {
       "text": "Remaining session: volume at V4–V5, footwork drills from Week 1.",
       "id": "remaining-session-volume-at"
      },
      {
       "text": "Session length: 90–100 min.",
       "id": "session-length-90-100-min"
      },
      {
       "text": "Drill: Hover hands — Hover each hand 1 second above the hold before gripping. Cuts slapping and teaches reading the hold first.",
       "name": "Drill: Hover hands",
       "detail": "Hover each hand 1 second above the hold before gripping. Cuts slapping and teaches reading the hold first.",
       "rx": "",
       "block": "Skill drill (optional)",
       "alts": [
        {
         "kind": "swap",
         "name": "Drill: Flag challenge",
         "detail": "Climb problems you've done using a flag (opposite leg out for balance) on every move you can."
        },
        {
         "kind": "swap",
         "name": "Drill: Open-hand only",
         "detail": "On V3–V4 problems use only open-hand grips — no crimping. Easier on a sore capsule and builds finger-friendly habits."
        },
        {
         "kind": "swap",
         "name": "Drill: Down-climb 3",
         "detail": "Down-climb three problems instead of jumping off. Eccentric control and body awareness."
        }
       ],
       "id": "drill-hover-hands"
      }
     ]
    },
    {
     "day": "Saturday",
     "title": "Active Recovery",
     "pre": null,
     "post": null,
     "items": [
      {
       "text": "Option A: 25–30 min brisk walk + Mobility Variant A or B.",
       "name": "Option A",
       "detail": "25–30 min brisk walk + Mobility Variant A or B.",
       "id": "option-a"
      },
      {
       "text": "Option B: Mobility Variant B only.",
       "name": "Option B",
       "detail": "Mobility Variant B only.",
       "id": "option-b"
      },
      {
       "text": "Option C: Full rest.",
       "name": "Option C",
       "detail": "Full rest.",
       "id": "option-c"
      }
     ]
    },
    {
     "day": "Sunday",
     "title": "Climbing: Lead, Try Grade Up",
     "pre": "A or D or F",
     "post": "A or F",
     "items": [
      {
       "text": "Lead warm-up at grade 15–16 for 15–20 min.",
       "id": "lead-warm-up-at-grade-15-16"
      },
      {
       "text": "5–6 laps at grade 17–18 with full rests.",
       "id": "5-6-laps-at-grade-17-18-with"
      },
      {
       "text": "1 attempt at grade 19. If it doesn't go, note exactly where.",
       "id": "1-attempt-at-grade-19-if-it"
      },
      {
       "text": "Breathing: exhale on every clip, exhale at every rest position.",
       "id": "breathing-exhale-on-every-cl"
      },
      {
       "text": "Drill: Controlled lead falls — Practise short controlled falls on clean overhanging gym routes with a trusted belayer. Confidence for the grade tests.",
       "name": "Drill: Controlled lead falls",
       "detail": "Practise short controlled falls on clean overhanging gym routes with a trusted belayer. Confidence for the grade tests.",
       "rx": "",
       "block": "Skill drill (optional)",
       "alts": [
        {
         "kind": "swap",
         "name": "Drill: Rope-management lap",
         "detail": "Climb a lap focusing only on rope handling: clip, check the rope path, lower off smoothly."
        },
        {
         "kind": "swap",
         "name": "Drill: Exhale on every clip",
         "detail": "Deliberately exhale on every clip and before every hard sequence. Reduces pump and tension."
        },
        {
         "kind": "swap",
         "name": "Drill: Find the rest",
         "detail": "On each route find at least three positions where you can drop an arm and shake out. Use them every time."
        }
       ],
       "id": "drill-controlled-lead-falls"
      }
     ]
    }
