       "detail": "3×10 per side, rest 75s. Light backpack (~5kg) held at the chest. Rear foot elevated on a chair, front foot far enough forward that the shin stays near-vertical. Upright torso, lower straight down. Stop if the tailbone or knee complains and reduce depth.",
