       "note": "",
       "cue": "Kneel with the hands in rings hung low. Brace the abs, ribs down, and roll the rings forward only as far as the lower back stays neutral — any sag means stop earlier. Pull back by squeezing the lats and abs. Anti-extension strength.",
       "rest": 45,
       "id": "ringfallout"
