       "text": "Single-leg RDL — 2×8 per side, rest 60s. Bodyweight only. Hinge at the hip with a soft bend in the standing knee. Raised leg trails and keeps the hips square. Back flat — the most important cue. Light fingertip on a wall for balance. Stop at once if sciatic symptoms appear.",
