    {
     "day": "Friday",
     "title": "Climbing: Project Day, Best Attempts",
     "pre": "C or E",
     "post": "C or E",
     "items": [
      {
       "text": "Warm up very thoroughly — 25 min.",
       "name": "Warm up very thoroughly",
       "detail": "25 min.",
       "id": "warm-up-very-thoroughly"
      },
      {
       "text": "Project: 4–5 burns, 5–6 min full rests. Approach each burn calm and methodical. This is the day to send your project.",
       "id": "project-4-5-burns-5-6-min-fu"
      },
      {
       "text": "Kilter board: 2 limit problems ×2 burns each if energy clearly allows.",
       "id": "kilter-board-2-limit-problem"
      },
      {
       "text": "Drill: Say it out loud — Read the whole problem from the ground and say each foot and hand move aloud before pulling on.",
       "name": "Drill: Say it out loud",
       "detail": "Read the whole problem from the ground and say each foot and hand move aloud before pulling on.",
       "rx": "",
       "block": "Skill drill (optional)",
       "alts": [
        {
         "kind": "swap",
         "name": "Drill: Lock-off drill",
         "detail": "On three problems, pause at each lock-off (elbow bent) for 2 seconds before the next move. Strength through position."
        },
        {
         "kind": "swap",
         "name": "Drill: Silent feet",
         "detail": "Place each foot so the shoe makes zero sound before the hands move. Forces precision and trust."
        },
        {
         "kind": "swap",
         "name": "Drill: Hover hands",
         "detail": "Hover each hand 1 second above the hold before gripping. Cuts slapping and teaches reading the hold first."
        }
       ],
       "id": "drill-say-it-out-loud"
      }
     ]
    },
    {
     "day": "Saturday",
     "title": "Light Recovery Only",
     "pre": null,
     "post": null,
     "items": [
      {
       "text": "Option A: Easy 20-min walk + Mobility Variant B. Save everything for your lead day.",
       "name": "Option A",
       "detail": "Easy 20-min walk + Mobility Variant B. Save everything for your lead day.",
       "id": "option-a"
      },
      {
       "text": "Option B: Mobility Variant B only.",
       "name": "Option B",
       "detail": "Mobility Variant B only.",
       "id": "option-b"
      },
      {
       "text": "Option C: Full rest — strongly recommended before a grade test day.",
       "name": "Option C: Full rest",
       "detail": "strongly recommended before a grade test day.",
       "id": "option-c-full-rest"
      }
     ]
    },
    {
     "day": "Sunday",
     "title": "Climbing: Lead Grade Test",
     "pre": "A or D or F",
     "post": "A or F",
     "items": [
      {
       "text": "Lead warm-up at 17–18 for 20–25 min. Take longer than usual.",
       "id": "lead-warm-up-at-17-18-for-20"
      },
      {
       "text": "3 laps at grade 19–20.",
       "id": "3-laps-at-grade-19-20"
      },
      {
       "text": "Grade test: best attempts at grade 21 and/or 22 with 10-min minimum rests between.",
       "id": "grade-test-best-attempts-at"
      },
      {
       "text": "Document the outcome — what felt possible, where it broke down, what has definitively changed since Week 1.",
       "name": "Document the outcome",
       "detail": "what felt possible, where it broke down, what has definitively changed since Week 1.",
       "id": "document-the-outcome"
      },
      {
       "text": "Drill: Find the rest — On each route find at least three positions where you can drop an arm and shake out. Use them every time.",
       "name": "Drill: Find the rest",
       "detail": "On each route find at least three positions where you can drop an arm and shake out. Use them every time.",
       "rx": "",
       "block": "Skill drill (optional)",
       "alts": [
        {
         "kind": "swap",
         "name": "Drill: Clip from the best stance",
         "detail": "Reach no higher than needed to clip and clip from the most stable stance. Shake out before the clip."
        },
        {
         "kind": "swap",
         "name": "Drill: Switch-hand clipping",
         "detail": "Clip with the weaker hand on the next route. Builds efficiency on routes where the clip hand isn't obvious."
        },
        {
         "kind": "swap",
         "name": "Drill: Quiet hands",
         "detail": "Hover each hand above the hold before grabbing. Keeps the rope drag down and the pace controlled."
        }
       ],
       "id": "drill-find-the-rest"
      }
     ]
    }
