       "text": "Lock-off holds — 3×12 seconds, rest 60s. Step or jump to the top position and hold the lock-off for the prescribed time: chin over the bar. Don't shrug. Lower slowly over 5 seconds. Lock-off strength is what holds your body in on hard moves.",
