    {
     "day": "Friday",
     "title": "Climbing: Boulder Grade Test",
     "pre": "A or C or E",
     "post": "C or E",
     "items": [
      {
       "text": "Warm up well — 20 min.",
       "name": "Warm up well",
       "detail": "20 min.",
       "id": "warm-up-well"
      },
      {
       "text": "Boulder grade test: 2–3 genuine attempts on a V7 problem or current project. Deloaded and fresh — this is your cleanest read on where bouldering stands after 12 weeks.",
       "id": "boulder-grade-test-2-3-genui"
      },
      {
       "text": "Drill: Hover hands — Hover each hand 1 second above the hold before gripping. Cuts slapping and teaches reading the hold first.",
       "name": "Drill: Hover hands",
       "detail": "Hover each hand 1 second above the hold before gripping. Cuts slapping and teaches reading the hold first.",
       "rx": "",
       "block": "Skill drill (optional)",
       "alts": [
        {
         "kind": "swap",
         "name": "Drill: Flag challenge",
         "detail": "Climb problems you've done using a flag (opposite leg out for balance) on every move you can."
        },
        {
         "kind": "swap",
         "name": "Drill: Open-hand only",
         "detail": "On V3–V4 problems use only open-hand grips — no crimping. Easier on a sore capsule and builds finger-friendly habits."
        },
        {
         "kind": "swap",
         "name": "Drill: Down-climb 3",
         "detail": "Down-climb three problems instead of jumping off. Eccentric control and body awareness."
        }
       ],
       "id": "drill-hover-hands"
      }
     ]
    },
    {
     "day": "Saturday",
     "title": "Full Mobility Day",
     "pre": null,
     "post": null,
     "items": [
      {
       "text": "Mobility Variant A followed by Variant B back-to-back (40 min). Best preparation for next cycle.",
       "id": "mobility-variant-a-followed"
      }
     ]
    },
    {
     "day": "Sunday",
     "title": "Climbing: Relaxed Lead",
     "pre": "A or D or F",
     "post": "A or F",
     "items": [
      {
       "text": "Relaxed lead at comfortable grades. Notice how much more confident and efficient you feel compared to Week 1.",
       "id": "relaxed-lead-at-comfortable"
      },
      {
       "text": "Session: 60–75 min.",
       "id": "session-60-75-min"
      },
      {
       "text": "Drill: Exhale on every clip — Deliberately exhale on every clip and before every hard sequence. Reduces pump and tension.",
       "name": "Drill: Exhale on every clip",
       "detail": "Deliberately exhale on every clip and before every hard sequence. Reduces pump and tension.",
       "rx": "",
       "block": "Skill drill (optional)",
       "alts": [
        {
         "kind": "swap",
         "name": "Drill: Find the rest",
         "detail": "On each route find at least three positions where you can drop an arm and shake out. Use them every time."
        },
        {
         "kind": "swap",
         "name": "Drill: Clip from the best stance",
         "detail": "Reach no higher than needed to clip and clip from the most stable stance. Shake out before the clip."
        },
        {
         "kind": "swap",
         "name": "Drill: Switch-hand clipping",
         "detail": "Clip with the weaker hand on the next route. Builds efficiency on routes where the clip hand isn't obvious."
        }
       ],
       "id": "drill-exhale-on-every-clip"
      }
     ]
    }
